-- functions
CREATE OR REPLACE FUNCTION public.apply_migration(p_version text, p_name text, p_sql text, p_checksum text, p_actor text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.schema_migrations where version = p_version) then
    return;                                    -- already applied; do nothing
  end if;

  execute p_sql;

  insert into public.schema_migrations (version, name, checksum, applied_by)
  values (p_version, p_name, p_checksum, p_actor);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_can_page(p_page text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role = 'admin'
      and (
        -- Super admins hold every page, as they do in resolvePerms().
        admin_role = 'super_admin'
        -- No explicit map: unchanged from before this migration. See the note
        -- above — inferring one from a role preset would duplicate the model.
        or admin_permissions -> 'pages' is null
        -- Explicit map: 'view' and 'edit' both grant read, 'none' and a missing
        -- key do not. Same two levels resolvePerms() treats as access.
        or coalesce(admin_permissions -> 'pages' ->> p_page, '') in ('view', 'edit')
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_is_admin()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND role = 'admin'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid()
      AND role = 'admin'
      AND coalesce(admin_role, 'super_admin') = 'super_admin'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.decrement_stock(p_product_id uuid, p_size text, p_qty integer, p_color_name text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id      uuid;
  v_changed integer := 0;
BEGIN
  IF p_product_id IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
    RETURN 0;
  END IF;

  v_id := zw_find_size_row(p_product_id, p_size, p_color_name);

  IF v_id IS NULL THEN
    RAISE WARNING 'decrement_stock: no row for product % size % colour %',
      p_product_id, p_size, coalesce(p_color_name, '(none)');
    RETURN 0;
  END IF;

  UPDATE product_sizes
  SET stock_quantity = GREATEST(0, coalesce(stock_quantity, 0) - p_qty)
  WHERE id = v_id;

  GET DIAGNOSTICS v_changed = ROW_COUNT;
  RETURN v_changed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_user(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'target_user_id is required';
  END IF;

  IF NOT public.current_user_is_admin() THEN
    RAISE EXCEPTION 'Only admins can delete users';
  END IF;

  IF auth.uid() = target_user_id THEN
    RAISE EXCEPTION 'Admins cannot delete their own account from the admin panel';
  END IF;

  DELETE FROM public.favorites WHERE user_id = target_user_id;
  UPDATE public.reviews SET user_id = NULL WHERE user_id = target_user_id;
  UPDATE public.orders SET user_id = NULL WHERE user_id = target_user_id;
  DELETE FROM public.profiles WHERE id = target_user_id;
  DELETE FROM auth.users WHERE id = target_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_admin_privilege_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.admin_role IS NOT DISTINCT FROM OLD.admin_role
     AND NEW.admin_permissions IS NOT DISTINCT FROM OLD.admin_permissions
     AND NEW.role IS NOT DISTINCT FROM OLD.role THEN
    RETURN NEW;                       -- nothing privilege-bearing changed
  END IF;

  -- Server-side writes. auth.uid() is NULL for the service role, which is how
  -- set-admin-role.js writes — and it has already checked RBAC and the limits.
  -- Without this the endpoint we want people using would be the one thing that
  -- stopped working.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT public.current_user_is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin can change roles or permissions (use the Users page)';
  END IF;

  -- Even a super admin, on their own row. Not because they lack the authority
  -- — they can grant it to somebody who grants it back — but because every
  -- self-promotion in the log should read as somebody else's decision. It also
  -- means one compromised session cannot quietly widen itself.
  IF auth.uid() = NEW.id THEN
    RAISE EXCEPTION 'You cannot change your own role or permissions';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (NEW.id, NEW.email, NEW.raw_user_meta_data->>'full_name', 'customer');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
$function$
;

