CREATE OR REPLACE FUNCTION public.prevent_profile_role_self_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() = NEW.id
     AND NEW.role IS DISTINCT FROM OLD.role
     AND NOT public.current_user_is_admin() THEN
    RAISE EXCEPTION 'Only admins can change profile roles';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_profile_role_self_elevation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Only intervene when a user is updating their own row
  IF auth.uid() = NEW.id AND OLD.role IS DISTINCT FROM NEW.role THEN
    -- Allow if the caller is already an admin; otherwise revert
    IF NOT current_user_is_admin() THEN
      NEW.role := OLD.role;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prune_error_log(p_batch integer DEFAULT 2000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total integer := 0;
  v_n     integer := 0;
  v_batch integer := greatest(1, least(coalesce(p_batch, 2000), 20000));
begin
  /* A CSP report matters while the violation is live. One that stopped two
     weeks ago is either fixed or nobody cares — and if it is still happening, a
     fresh row is being written right now. */
  delete from error_log
  where ctid in (
    select ctid from error_log
    where source = 'csp' and created_at < now() - interval '14 days'
    limit v_batch
  );
  get diagnostics v_n = row_count;
  v_total := v_total + v_n;

  /* Real errors get a quarter. Long enough to see a pattern, short enough that
     this table cannot become the biggest thing in a 500 MB database. */
  delete from error_log
  where ctid in (
    select ctid from error_log
    where source <> 'csp' and created_at < now() - interval '90 days'
    limit v_batch
  );
  get diagnostics v_n = row_count;
  return v_total + v_n;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.record_api_status(p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return 0;
  end if;

  insert into api_status_log (service, ok, configured, detail)
  select
    left(r->>'service', 64),
    coalesce((r->>'ok')::boolean, false),
    (r->>'configured')::boolean,
    left(r->>'detail', 500)          -- recognising a repeat, not storing a trace
  from jsonb_array_elements(p_rows) as r
  where coalesce(r->>'service', '') <> '';

  get diagnostics v_count = row_count;

  /* Kept to 30 days, here rather than in a scheduled job, because a job nobody
     runs is how this table becomes the biggest thing in the database. Only
     fires occasionally — a delete on every write is pure overhead once the old
     rows are already gone. */
  if random() < 0.02 then
    delete from api_status_log where checked_at < now() - interval '30 days';
  end if;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.restock_stock(p_product_id uuid, p_size text, p_qty integer, p_color_name text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id      uuid;
  v_changed integer := 0;
BEGIN
  IF p_product_id IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
    RETURN 0;
  END IF;

  v_id := zw_find_size_row(p_product_id, p_size, p_color_name);

  IF v_id IS NULL THEN
    RAISE WARNING 'restock_stock: no row for product % size % colour %',
      p_product_id, p_size, coalesce(p_color_name, '(none)');
    RETURN 0;
  END IF;

  -- No upper clamp: stock coming back from a return is a real count, and a
  -- ceiling here would silently swallow it.
  UPDATE product_sizes
  SET stock_quantity = coalesce(stock_quantity, 0) + p_qty
  WHERE id = v_id;

  GET DIAGNOSTICS v_changed = ROW_COUNT;
  RETURN v_changed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reviews_guard_photo_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if not public.current_user_is_admin() then
    new.photos_approved := false;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

