CREATE OR REPLACE FUNCTION public.zw_canon_size(p_size text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN s ~ '^([2-5])x(s|l)$' THEN repeat('x', (substring(s from 1 for 1))::int) || substring(s from 3)
    ELSE s
  END
  FROM (SELECT lower(regexp_replace(coalesce(p_size, ''), '\s', '', 'g')) AS s) t;
$function$
;

CREATE OR REPLACE FUNCTION public.zw_find_size_row(p_product_id uuid, p_size text, p_color_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF p_product_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- 1) The colour actually named, matched the way the storefront matches it.
  IF p_color_name IS NOT NULL AND btrim(p_color_name) <> '' THEN
    SELECT id INTO v_id
    FROM product_sizes
    WHERE product_id = p_product_id
      AND zw_canon_size(size) = zw_canon_size(p_size)
      AND lower(btrim(coalesce(color_name, ''))) = lower(btrim(p_color_name))
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;

  -- 2) Colour-agnostic rows ONLY. A row with color_name NULL genuinely covers
  --    every colourway. Another COLOUR's row describes a different garment, and
  --    reaching for it is what made a sold colour never go down while an unsold
  --    one drained to zero.
  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM product_sizes
    WHERE product_id = p_product_id
      AND zw_canon_size(size) = zw_canon_size(p_size)
      AND color_name IS NULL
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;

  RETURN v_id;   -- NULL means nothing describes this garment. Say so; do not guess.
END;
$function$
;

CREATE OR REPLACE FUNCTION public.zw_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_headers json;
  v_ip text;
  v_limit int := tg_argv[0]::int;
  v_window interval := tg_argv[1]::interval;
  v_count int;
begin
  -- Backend (service role) is never throttled.
  if coalesce(current_setting('request.jwt.claims', true)::json->>'role','') = 'service_role' then
    return new;
  end if;

  begin
    v_headers := current_setting('request.headers', true)::json;
  exception when others then
    v_headers := null;
  end;
  v_ip := coalesce(
    v_headers->>'cf-connecting-ip',
    split_part(coalesce(v_headers->>'x-forwarded-for',''), ',', 1),
    ''
  );
  -- No client IP (e.g. SQL console) — don't blind-throttle.
  if v_ip is null or v_ip = '' then
    return new;
  end if;

  select count(*) into v_count
  from public.zw_insert_throttle
  where bucket = tg_table_name and ip = v_ip and created_at > now() - v_window;

  if v_count >= v_limit then
    raise exception 'Too many submissions. Please try again later.';
  end if;

  insert into public.zw_insert_throttle (bucket, ip) values (tg_table_name, v_ip);
  -- Opportunistic cleanup of old ledger rows (~1% of inserts).
  if random() < 0.01 then
    delete from public.zw_insert_throttle where created_at < now() - interval '2 days';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.zw_review_language_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_text text;
begin
  if tg_op = 'UPDATE'
     and new.title is not distinct from old.title
     and new.body is not distinct from old.body
     and new.nickname is not distinct from old.nickname
     and new.reviewer_name is not distinct from old.reviewer_name then
    return new;
  end if;

  v_text := coalesce(new.title,'') || ' ' || coalesce(new.body,'') || ' '
         || coalesce(new.nickname,'') || ' ' || coalesce(new.reviewer_name,'');

  if exists (
    select 1 from public.zw_banned_words
    where v_text ~* ('\m' || word || '\M')
  ) then
    raise exception 'Your review contains language we can''t publish. Please remove any profanity and try again.';
  end if;

  return new;
end;
$function$
;


-- triggers
CREATE TRIGGER protect_admin_privilege_columns BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION guard_admin_privilege_columns();
CREATE TRIGGER protect_profile_role BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION prevent_profile_role_self_elevation();
CREATE TRIGGER protect_profile_role_self_change BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION prevent_profile_role_self_change();
CREATE TRIGGER reviews_photo_approval_guard BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION reviews_guard_photo_approval();
CREATE TRIGGER trg_return_requests_updated_at BEFORE UPDATE ON public.return_requests FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER zw_rate_limit_restock BEFORE INSERT ON public.restock_requests FOR EACH ROW EXECUTE FUNCTION zw_rate_limit('5', '1 hour');
CREATE TRIGGER zw_rate_limit_reviews BEFORE INSERT ON public.reviews FOR EACH ROW EXECUTE FUNCTION zw_rate_limit('5', '1 hour');
CREATE TRIGGER zw_rate_limit_waitlist BEFORE INSERT ON public.waitlist FOR EACH ROW EXECUTE FUNCTION zw_rate_limit('5', '1 hour');
CREATE TRIGGER zw_review_language_check BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION zw_review_language_check();

