-- policies
create policy "Admins can insert audit log" on public."admin_audit_log" for insert to "authenticated" with check (((admin_user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::text))))));
create policy "Admins can read audit log" on public."admin_audit_log" for select to "authenticated" using ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::text)))));
